def solve(payload):
    import re
    def normalize(value):
        if not value.isascii():
            return None
        value = value.lower()
        if value.endswith("."):
            value = value[:-1]
        if not 1 <= len(value) <= 253:
            return None
        labels = value.split(".")
        if any(not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", label) for label in labels):
            return None
        return value
    rules = []
    for rule in payload["rules"]:
        domain = normalize(rule["domain"])
        if domain is None or rule["action"] not in ("allow", "deny"):
            return {"error": "invalid_rule"}
        rules.append((domain, rule["subdomains"], rule["action"]))
    decisions = []
    for query in payload["queries"]:
        domain = normalize(query)
        if domain is None:
            decisions.append("invalid")
            continue
        matches = [(len(base.split(".")), action) for base, subdomains, action in rules if domain == base or (subdomains and domain.endswith("."+base))]
        if not matches:
            decisions.append("deny")
        else:
            level = max(n for n, _ in matches)
            decisions.append("deny" if any(n == level and action == "deny" for n, action in matches) else "allow")
    return {"decisions": decisions}
